		hasWatermark = st.hasMax
	}

	type candidate struct {
		raw       rawEvent
		ctx       *eventContext
		ev        *Event
		duplicate bool
	}
	var candidates []candidate
	var auditEntries []auditLogEntry
	var rejectRecords []rejectRecord

	// First pass: validation, watermark admission, cross-run dedup, and watermark advancement.
	for _, raw := range events {
		ctx := newContext(raw)
		bucket := "invalid"
		reason := ""
		var ev *Event
		if raw.Invalid {
			bucket = "invalid"
			reason = "invalid_json"
		} else {
			ev, reason = parseEvent(ctx, rt, cfg.ratesStrict, cfg.ratesMaxStaleness)
			if ev != nil {
				if seen[ev.ID] {
					bucket = "duplicate"
					reason = "cross_run"
					bucketCounts[bucket]++
					duplicateReasons["cross_run"]++
					auditEntries = append(auditEntries, auditLogEntry{
						Shard:  raw.Shard,
						Line:   raw.Line,
						ID:     ctx.IDStr(),
						TS:     ctx.TSString(),
						Type:   ctx.TypeString(),
						Bucket: bucket,
						Reason: reason,
						Event:  raw.Raw,
					})
					rejectRecords = append(rejectRecords, rejectRecord{bucket: bucket, reason: reason, raw: raw.Raw})
					continue
				} else if ev.TS.Before(watermark) || ev.TS.Equal(watermark) {
					bucket = "late"
					reason = "late"
					ev = nil
				} else {
					bucket = "accepted"
					if !hasMin || ev.TS.Before(minTs) {
						minTs = ev.TS
						hasMin = true
					}
					if !hasMax || ev.TS.After(maxTs) {
						maxTs = ev.TS
						hasMax = true
					}
					if ev.TS.After(watermark) {
						watermark = ev.TS
						hasWatermark = true
					}
				}
			} else {
				bucket = "invalid"
			}
		}
		if bucket == "invalid" {
			invalidReasons[reason]++
		}
		bucketCounts[bucket]++
		if bucket != "accepted" {
			rejectRecords = append(rejectRecords, rejectRecord{bucket: bucket, reason: reason, raw: raw.Raw})
		}
		candidates = append(candidates, candidate{raw: raw, ctx: ctx, ev: ev, duplicate: false})
		auditEntries = append(auditEntries, auditLogEntry{
			Shard:  raw.Shard,
			Line:   raw.Line,
			ID:     ctx.IDStr(),
			TS:     ctx.TSString(),
			Type:   ctx.TypeString(),
			Bucket: bucket,
			Reason: reason,
			Event:  raw.Raw,
		})
	}

