	groups := map[string][]int{}
	for i, c := range candidates {
		if c.ev != nil {
			groups[c.ev.ID] = append(groups[c.ev.ID], i)
		}
	}
	winnerSet := map[int]bool{}
	winners := map[string]int{}
	var dedupPolicyStats dedupPolicyStats
	dedupPolicyStats.Policy = cfg.dedupPolicy
	for _, id := range sortedKeys(map[string]bool{}) {
		_ = id
	}
	for id, idxs := range groups {
		if len(idxs) < 2 {
			if len(idxs) == 1 {
				winners[id] = idxs[0]
				winnerSet[idxs[0]] = true
			}
			continue
		}
		winner := idxs[0]
		for _, idx := range idxs[1:] {
			if cfg.dedupPolicy == "first-arrival" {
				if arrivalLess(candidates[idx].ev, candidates[winner].ev) {
					winner = idx
				}
			} else {
				if candidates[idx].ev.TS.After(candidates[winner].ev.TS) {
					winner = idx
				}
			}
		}
		winners[id] = winner
		winnerSet[winner] = true
		sameShard := true
		for _, idx := range idxs {
			if candidates[idx].ev.Shard != candidates[winner].ev.Shard {
				sameShard = false
				break
			}
		}
		if sameShard {
			dedupPolicyStats.DuplicateWinnersSameShard++
			dedupPolicyStats.DuplicateWinnersLineTiebreak++
		} else {
			dedupPolicyStats.DuplicateWinnersCrossShard++
		}
	}

