	bucketCounts["accepted"] = 0
	for i, c := range candidates {
		if c.ev == nil {
			continue
		}
		if winnerSet[i] {
			bucketCounts["accepted"]++
			shardAccepted[c.ev.Shard]++
			seen[c.ev.ID] = true
			_ = pending
			_ = openSessions
		} else {
			bucketCounts["duplicate"]++
			duplicateReasons["same_run"]++
			entry := auditEntries[i]
			entry.Bucket = "duplicate"
			entry.Reason = "same_run"
			if cfg.dedupPolicy == "first-arrival" {
				w := winners[entry.ID]
				entry.WinnerArrival = &winnerArrival{Shard: candidates[w].ev.Shard, Line: candidates[w].ev.Line}
			}
			auditEntries[i] = entry
			rejectRecords = append(rejectRecords, rejectRecord{bucket: "duplicate", reason: "same_run", raw: c.raw.Raw, winner: true, winnerShard: candidates[winners[c.ev.ID]].ev.Shard, winnerLine: candidates[winners[c.ev.ID]].ev.Line})
		}
	}

	summary := summaryOutput{
		TotalEvents:    len(events),
		AcceptedEvents: bucketCounts["accepted"],
		RejectedEvents: bucketCounts["duplicate"] + bucketCounts["invalid"] + bucketCounts["late"] + bucketCounts["unresolved_chargeback"],
		Anomalies: map[string]int{
			"duplicate":             bucketCounts["duplicate"],
			"invalid":               bucketCounts["invalid"],
			"late":                  bucketCounts["late"],
			"unresolved_chargeback": bucketCounts["unresolved_chargeback"],
		},
		RunIndex: runIndex,
	}
	if hasWatermark {
		wm := formatTS(watermark)
		summary.Watermark = &wm
	}
	summaryData, err := json.MarshalIndent(summary, "", "  ")
	if err != nil {
		return err
	}
	summaryData = append(summaryData, '\n')
	if err := atomicWriteFile(cfg.outputPath, summaryData); err != nil {
		return err
	}
	rejectsData := buildRejects(rejectRecords, cfg.dedupPolicy)
	if err := atomicWriteFile(cfg.rejectsPath, rejectsData); err != nil {
		return err
	}
	if cfg.stateOut != "" {
