		if err := atomicWriteFile(cfg.stateOut, stateData); err != nil {
			return err
		}
	}
	if cfg.auditLog != "" {
		var buf bytes.Buffer
		for _, e := range auditEntries {
			b, err := json.Marshal(e)
			if err != nil {
				return err
			}
			buf.Write(b)
			buf.WriteByte('\n')
		}
		if err := atomicWriteFile(cfg.auditLog, buf.Bytes()); err != nil {
