			SHA256:           auditSHA,
		}
		if cfg.dedupPolicySet {
			digest.DedupPolicyStats = &dedupPolicyStats
		}
		data, err := json.MarshalIndent(digest, "", "  ")
		if err != nil {
			return err
		}
		data = append(data, '\n')
		if err := atomicWriteFile(cfg.auditLogDigest, data); err != nil {
			return err
		}
	}
