				winner = idx
			}
		} else {
			cts := candidates[idx].ctx.TSString()
			wts := candidates[winner].ctx.TSString()
			if cts > wts {
				winner = idx
				tiebreak = false
			} else if cts == wts && arrivalLess(candidates[idx].ev, candidates[winner].ev) {
				winner = idx
				tiebreak = true
			}
		}
	}
	if cfg.dedupPolicy == "lex-largest-ts" {
		wts := candidates[winner].ctx.TSString()
		for _, idx := range idxs {
			if idx != winner && candidates[idx].ctx.TSString() == wts {
				tiebreak = true
				break
			}
		}
	}
	winners[id] = winner
	winnerSet[winner] = true
	sameShard := true
	for _, idx := range idxs {
		if candidates[idx].ev.Shard != candidates[winner].ev.Shard {
			sameShard = false
			break
		}
	}
	if sameShard {
		dedupPolicyStats.DuplicateWinnersSameShard++
		if cfg.dedupPolicy == "first-arrival" || tiebreak {
			dedupPolicyStats.DuplicateWinnersLineTiebreak++
		}
	} else {
		dedupPolicyStats.DuplicateWinnersCrossShard++
	}
'''
s=s[:start]+new_winner+s[end:]

# Replace finalization block to reset min/max and mark seen IDs.
start=s.index('\t// Finalize accepted/duplicate buckets and outputs in arrival order.')
end=s.index('\n\tvar rejectRecords []rejectRecord')
new_final=r'''	// Finalize accepted/duplicate buckets and outputs in arrival order.
	hasMin, hasMax = false, false
	for _, c := range candidates {
		if c.ev != nil {
			seen[c.ev.ID] = true
		}
	}
	bucketCounts["accepted"] = 0
	bucketCounts["duplicate"] = duplicateReasons["cross_run"]
	for i, c := range candidates {
		_ = i
		if c.ev == nil {
			continue
		}
		if winnerSet[i] {
			bucketCounts["accepted"]++
			shardAccepted[c.ev.Shard]++
			if !hasMin || c.ev.TS.Before(minTs) {
				minTs = c.ev.TS
				hasMin = true
			}
			if !hasMax || c.ev.TS.After(maxTs) {
				maxTs = c.ev.TS
				hasMax = true
			}
			_ = pending
			_ = openSessions
		} else {
			bucketCounts["duplicate"]++
			duplicateReasons["same_run"]++
			entry := auditEntries[i]
			entry.Bucket = "duplicate"
			entry.Reason = "same_run"
			if cfg.dedupPolicy == "first-arrival" {
				w := winners[entry.ID]
				entry.WinnerArrival = &winnerArrival{Shard: candidates[w].ev.Shard, Line: candidates[w].ev.Line}
			}
			auditEntries[i] = entry
		}
	}
'''
s=s[:start]+new_final+s[end:]

# Only emit dedup_policy_stats when audit log, digest, and first-arrival policy are present.
s=s.replace('''		if cfg.dedupPolicySet {
			digest.DedupPolicyStats = &dedupPolicyStats
		}''', '''		if cfg.dedupPolicySet && cfg.auditLog != "" && cfg.dedupPolicy == "first-arrival" {
			digest.DedupPolicyStats = &dedupPolicyStats
		}''')

p.write_text(s)
PY

